import sys
import os
import hashlib
import argparse
from typing import Dict, Optional

def load_secrets(file_path: str, passphrase: str) -> Optional[Dict[str, str]]:
    try:
        with open(file_path, 'rb') as f:
            data = f.read()
            if len(data) < 16:
                return None
            # Verify passphrase
            expected_hash = hashlib.sha256(passphrase.encode()).digest()
            if data[:16] != expected_hash:
                return None
            # Verify file integrity
            if len(data) < 32:
                return None
            file_checksum = data[16:32]
            current_checksum = hashlib.sha256(data[32:]).digest()
            if file_checksum != current_checksum:
                return None
            # Load secrets
            secrets = {}
            offset = 32
            while offset < len(data):
                name_len = data[offset]
                if offset + name_len + 1 > len(data):
                    break
                name = data[offset+1:offset+1+name_len].decode('utf-8')
                secret_len = data[offset+1+name_len]
                if offset + 1 + name_len + secret_len > len(data):
                    break
                secret = data[offset+2+name_len:offset+2+name_len+secret_len].decode('utf-8')
                secrets[name] = secret
                offset += 1 + name_len + secret_len
            return secrets
    except (IOError, UnicodeDecodeError):
        return None

def save_secrets(file_path: str, passphrase: str, secrets: Dict[str, str]) -> bool:
    try:
        pass_hash = hashlib.sha256(passphrase.encode()).digest()
        file_data = pass_hash + hashlib.sha256(b''.join(secrets.values()).encode()).digest()
        for name, secret in secrets.items():
            name_bytes = name.encode('utf-8')
            file_data += len(name_bytes).to_bytes(1, 'big') + name_bytes + len(secret).to_bytes(1, 'big') + secret.encode('utf-8')
        with open(file_path, 'wb') as f:
            f.write(file_data)
        return True
    except IOError:
        return False

def process_command(secrets: Dict[str, str], command: str) -> Optional[str]:
    parts = command.split()
    if not parts:
        return None
    if parts[0] == 'set':
        if len(parts) < 3:
            return None
        name = parts[1]
        secret = ' '.join(parts[2:])
        secrets[name] = secret
        return None
    elif parts[0] == 'get':
        if len(parts) < 2:
            return None
        name = parts[1]
        return secrets.get(name, 'ERROR: not found')
    elif parts[0] == 'list':
        sorted_names = sorted(secrets.keys())
        return '\n'.join(sorted_names)
    return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python secrets.py <file_path>")
        sys.exit(1)

    file_path = sys.argv[1]
    passphrase = os.getenv('SECRETS_PASSPHRASE')
    if not passphrase:
        print("ERROR: SECRETS_PASSPHRASE environment variable not set")
        sys.exit(1)

    secrets = load_secrets(file_path, passphrase)
    if secrets is None:
        print("ERROR: bad passphrase")
        sys.exit(2)

    found_error = False
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        result = process_command(secrets, line)
        if result is not None:
            print(result)

    if 'ERROR: not found' in sys.stdin.read():
        found_error = True

    if found_error:
        sys.exit(1)

    if not save_secrets(file_path, passphrase, secrets):
        print("ERROR: failed to save secrets")
        sys.exit(3)

if __name__ == '__main__':
    main()

import os
import sys
import hashlib
import json
import argparse
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes

class SecretsManager:
    def __init__(self, filename):
        self.filename = filename
        self.key = None
        self.iv = None
        self.data = {}
        self.load()

    def load(self):
        if not os.path.exists(self.filename):
            return

        try:
            with open(self.filename, 'rb') as f:
                header = f.read(16)
                if len(header) != 16:
                    print("ERROR: file modified", file=sys.stderr)
                    sys.exit(3)
                self.key = get_random_bytes(16)
                self.iv = get_random_bytes(16)
                data = f.read()
                if len(data) < 32:
                    print("ERROR: file modified", file=sys.stderr)
                    sys.exit(3)
                encrypted_data = data[32:]
                decrypted_data = self._decrypt(encrypted_data)
                try:
                    self.data = json.loads(decrypted_data.decode('utf-8'))
                except json.JSONDecodeError:
                    print("ERROR: file modified", file=sys.stderr)
                    sys.exit(3)
        except Exception:
            pass

    def _generate_key(self):
        passphrase = os.getenv('SECRETS_PASSPHRASE')
        if not passphrase:
            print("ERROR: bad passphrase", file=sys.stderr)
            sys.exit(2)
        key = hashlib.sha256(passphrase.encode('utf-8')).digest()
        if len(key) != 32:
            print("ERROR: bad passphrase", file=sys.stderr)
            sys.exit(2)
        return key[:16], key[16:32]

    def _encrypt(self, data):
        key, iv = self._generate_key()
        cipher = AES.new(iv, AES.MODE_CBC)
        padded_data = pad(data.encode('utf-8'), AES.block_size)
        return cipher.encrypt(padded_data)

    def _decrypt(self, encrypted_data):
        key, iv = self._generate_key()
        cipher = AES.new(iv, AES.MODE_CBC)
        decrypted_data = cipher.decrypt(encrypted_data)
        return unpad(decrypted_data, AES.block_size)

    def save(self):
        if not self.key or not self.iv:
            self.key, self.iv = self._generate_key()
        encrypted_data = self._encrypt(json.dumps(self.data).encode('utf-8'))
        with open(self.filename, 'wb') as f:
            f.write(self.key + self.iv + encrypted_data)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('filename')
    args = parser.parse_args()

    manager = SecretsManager(args.filename)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split(maxsplit=2)
        if parts[0] == 'set':
            if len(parts) != 3:
                continue
            name, secret = parts[1], parts[2]
            manager.data[name] = secret
        elif parts[0] == 'get':
            if len(parts) != 2:
                continue
            name = parts[1]
            if name in manager.data:
                print(manager.data[name])
            else:
                print("ERROR: not found")
                sys.exit(1)
        elif parts[0] == 'list':
            for name in sorted(manager.data.keys()):
                print(name)

    manager.save()

if __name__ == '__main__':
    main()

import argparse
import base64
import hashlib
import os
import sys
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes

class SecretsManager:
    def __init__(self, file_path):
        self.file_path = file_path
        self.secrets = {}
        self.passphrase = os.getenv('SECRETS_PASSPHRASE')
        if not self.passphrase:
            raise ValueError("SECRETS_PASSPHRASE environment variable not set")

    def _encrypt(self, data):
        key = hashlib.sha256(self.passphrase.encode()).digest()
        iv = get_random_bytes(16)
        cipher = AES.new(key, AES.MODE_CBC, iv)
        ct_bytes = cipher.encrypt(pad(data.encode(), AES.block_size))
        return base64.b64encode(iv + ct_bytes).decode()

    def _decrypt(self, encrypted_data):
        key = hashlib.sha256(self.passphrase.encode()).digest()
        encrypted_data = encrypted_data.encode()
        iv = encrypted_data[:16]
        ct = encrypted_data[16:]
        cipher = AES.new(key, AES.MODE_CBC, iv)
        return unpad(cipher.decrypt(ct), AES.block_size).decode()

    def _load(self):
        try:
            with open(self.file_path, 'rb') as f:
                encrypted_data = f.read()
                decrypted_data = self._decrypt(encrypted_data)
                self.secrets = eval(decrypted_data)
        except (FileNotFoundError, ValueError, KeyError):
            self.secrets = {}

    def _save(self):
        with open(self.file_path, 'wb') as f:
            encrypted_data = self._encrypt(str(self.secrets))
            f.write(encrypted_data.encode())

    def _check_integrity(self):
        try:
            with open(self.file_path, 'rb') as f:
                f.seek(0, os.SEEK_END)
                file_size = f.tell()
                f.seek(0)
                file_data = f.read()
                if file_size != len(file_data):
                    return False
                return True
        except (IOError, OSError):
            return False

    def process(self):
        self._load()
        if not self._check_integrity():
            print("ERROR: file modified", file=sys.stderr)
            sys.exit(3)

        try:
            for line in sys.stdin:
                line = line.strip()
                if not line:
                    continue
                parts = line.split(maxsplit=2)
                if not parts:
                    continue
                cmd = parts[0]
                if cmd == 'set':
                    if len(parts) != 3:
                        continue
                    name, secret = parts[1], parts[2]
                    self.secrets[name] = secret
                elif cmd == 'get':
                    if len(parts) != 2:
                        continue
                    name = parts[1]
                    if name in self.secrets:
                        print(self.secrets[name])
                    else:
                        print("ERROR: not found", file=sys.stderr)
                        self.exit_on_error()
                elif cmd == 'list':
                    for name in sorted(self.secrets.keys()):
                        print(name)
        except Exception:
            print("ERROR: bad passphrase", file=sys.stderr)
            sys.exit(2)
        self._save()
        sys.exit(0)

    def exit_on_error(self):
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('file_path')
    args = parser.parse_args()
    manager = SecretsManager(args.file_path)
    manager.process()

if __name__ == '__main__':
    main()

import argparse
import os
import sys
import hashlib
import json
import binascii
from typing import Dict, Optional

def load_secret_map(file_path: str, passphrase: str) -> Optional[Dict[str, str]]:
    try:
        with open(file_path, 'rb') as f:
            data = f.read()
            if not data:
                return None
            # Verify file integrity by rehashing
            expected_hash = hashlib.sha256(passphrase.encode()).digest()
            if len(data) < 32:
                return None
            actual_hash = data[:32]
            if not binascii.hexlify(actual_hash) == binascii.hexlify(expected_hash):
                return None
            # Verify file content
            try:
                decrypted_data = hashlib.sha256(data[32:].decode('utf-8')).digest()
                if not binascii.hexlify(decrypted_data) == binascii.hexlify(expected_hash):
                    return None
                return json.loads(data[32:].decode('utf-8'))
            except json.JSONDecodeError:
                return None
    except (IOError, UnicodeDecodeError):
        return None
    return None

def save_secret_map(file_path: str, passphrase: str, secret_map: Dict[str, str]) -> bool:
    try:
        encrypted_data = hashlib.sha256(passphrase.encode()).digest() + json.dumps(secret_map).encode('utf-8')
        with open(file_path, 'wb') as f:
            f.write(encrypted_data)
        return True
    except (IOError, UnicodeEncodeError):
        return False

def verify_file_integrity(file_path: str, passphrase: str) -> bool:
    try:
        with open(file_path, 'rb') as f:
            data = f.read()
            if not data:
                return False
            expected_hash = hashlib.sha256(passphrase.encode()).digest()
            if len(data) < 32:
                return False
            actual_hash = data[:32]
            if not binascii.hexlify(actual_hash) == binascii.hexlify(expected_hash):
                return False
            return True
    except (IOError, UnicodeDecodeError):
        return False

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('file_path', type=str)
    args = parser.parse_args()

    if not os.getenv('SECRETS_PASSPHRASE'):
        print("ERROR: SECRETS_PASSPHRASE environment variable not set", file=sys.stderr)
        sys.exit(2)

    passphrase = os.getenv('SECRETS_PASSPHRASE')
    secret_map = {}

    if os.path.exists(args.file_path):
        loaded_map = load_secret_map(args.file_path, passphrase)
        if loaded_map is None:
            print("ERROR: bad passphrase", file=sys.stderr)
            sys.exit(2)
        if not verify_file_integrity(args.file_path, passphrase):
            print("ERROR: file modified", file=sys.stderr)
            sys.exit(3)
        secret_map = loaded_map

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split(maxsplit=2)
        if not parts:
            continue
        cmd = parts[0]
        if cmd == 'set':
            if len(parts) < 3:
                continue
            name, secret = parts[1], parts[2]
            secret_map[name] = secret
        elif cmd == 'get':
            if len(parts) < 2:
                continue
            name = parts[1]
            if name in secret_map:
                print(secret_map[name])
            else:
                print("ERROR: not found", file=sys.stderr)
                sys.exit(1)
        elif cmd == 'list':
            for name in sorted(secret_map.keys()):
                print(name)

    if save_secret_map(args.file_path, passphrase, secret_map):
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == '__main__':
    main()
